"""Reproduction tests for unique_items.py, generated by Debug GYM."""

from unique_items import unique_items


def test_empty_list() -> None:
    assert unique_items([]) == []


def test_already_unique() -> None:
    assert unique_items([1, 2, 3]) == [1, 2, 3]


def test_repeated_values() -> None:
    assert unique_items([2, 2, 3, 2]) == [2, 3]
